def api_clients_list(api_key, status=None, name_query=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0164000" if __import__("os").path.isdir("./environment_mix/0164000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validation
    if _extra:
        return _err("VALIDATION_ERROR", f"Unknown field(s): {', '.join(sorted(_extra.keys()))}")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")
    if name_query is not None and not isinstance(name_query, str):
        return _err("VALIDATION_ERROR", "name_query must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_inv_id():
        return "eco_inv_" + uuid.uuid4().hex[:26]

    def _parse_dt_any(s):
        if not isinstance(s, str) or not s:
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _auth_client(key):
        k = key.strip()
        for c in clients if isinstance(clients, list) else []:
            if not isinstance(c, dict):
                continue
            pfx = c.get("api_key_prefix")
            if k == c.get("id") or k == pfx:
                return c
            if isinstance(pfx, str) and pfx and k.startswith(pfx):
                return c
            if k == c.get("api_key_hash"):
                return c
        return None

    def _rate_limited(client_row):
        if not isinstance(client_row, dict):
            return False, 0, None, None
        rl = client_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            return False, 0, rl, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for inv in invocations if isinstance(invocations, list) else []:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != client_row.get("id"):
                continue
            dt = _parse_dt_any(inv.get("created_at"))
            if dt is not None and dt >= cutoff:
                used += 1
        return used >= rl, used, rl, max(0, rl - used)

    def _record(tool_name, client_row, req_obj, status_val, http_status_code=None,
                response_json=None, error_code=None, error_message=None):
        now = _now_iso()
        inv = {
            "id": _gen_inv_id(),
            "client_id": (client_row.get("id") if isinstance(client_row, dict) else None),
            "tool_name": tool_name,
            "status": "received",
            "request_json": req_obj if isinstance(req_obj, dict) else {},
            "response_json": None,
            "http_status_code": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "ip_address": None,
            "user_agent": None,
            "trace_id": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        inv["status"] = "processing"
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        inv["status"] = status_val
        inv["http_status_code"] = http_status_code
        inv["response_json"] = response_json
        inv["error_code"] = error_code
        inv["error_message"] = error_message
        inv["duration_ms"] = int(max(0, min(300000, round((time.time() - t0) * 1000))))
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        return inv["id"]

    authed = _auth_client(api_key)
    if authed is None:
        inv_id = _record("version", None, {"api_key": api_key}, "failed", http_status_code=401,
                         error_code="invalid_api_key", error_message="Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key", http_status_code=401, invocation_id=inv_id)
    if authed.get("status") != "active":
        inv_id = _record("version", authed, {"api_key": api_key}, "failed", http_status_code=403,
                         error_code="client_disabled", error_message="Client is not active; access denied")
        return _err("UNAUTHORIZED", "Client is not active; access denied", http_status_code=403, invocation_id=inv_id)

    limited, used, rl, remaining = _rate_limited(authed)
    if limited:
        inv_id = _record("version", authed, {"api_key": api_key}, "failed", http_status_code=429,
                         error_code="rate_limited",
                         error_message=f"Rate limit exceeded: allowed {rl}/min; retry after 1s")
        return _err("RATE_LIMIT", "Rate limit exceeded", http_status_code=429, invocation_id=inv_id, limit=rl, used=used, remaining=remaining)

    # Apply filters
    rows = [c for c in (clients if isinstance(clients, list) else []) if isinstance(c, dict)]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if name_query is not None:
        nq = name_query.casefold()
        rows = [c for c in rows if isinstance(c.get("name"), str) and nq in c["name"].casefold()]

    # Stable sort by id (acts like cursor)
    rows.sort(key=lambda r: (str(r.get("id") or "")))

    # Cursor: return rows strictly after cursor id
    if cursor:
        rows = [r for r in rows if isinstance(r.get("id"), str) and r["id"] > cursor]

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = page[-1]["id"] if (has_more and page and isinstance(page[-1].get("id"), str)) else None

    # Update last_seen_at for authed client
    now_iso = _now_iso()
    for c in clients if isinstance(clients, list) else []:
        if isinstance(c, dict) and c.get("id") == authed.get("id"):
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso
            _save("api_clients.json", clients)
            break

    resp = {
        "data": page,
        "meta": {"total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "limit": limit},
    }
    inv_id = _record("version", authed, {"status": status, "name_query": name_query, "limit": limit, "cursor": cursor}, "succeeded", http_status_code=200, response_json=resp)
    resp["invocation_id"] = inv_id
    return resp

def api_clients_get(api_key, id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0164000" if __import__("os").path.isdir("./environment_mix/0164000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if _extra:
        return _err("VALIDATION_ERROR", f"Unknown field(s): {', '.join(sorted(_extra.keys()))}")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_inv_id():
        return "eco_inv_" + uuid.uuid4().hex[:26]

    def _parse_dt_any(s):
        if not isinstance(s, str) or not s:
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _auth_client(key):
        k = key.strip()
        for c in clients if isinstance(clients, list) else []:
            if not isinstance(c, dict):
                continue
            pfx = c.get("api_key_prefix")
            if k == c.get("id") or k == pfx:
                return c
            if isinstance(pfx, str) and pfx and k.startswith(pfx):
                return c
            if k == c.get("api_key_hash"):
                return c
        return None

    def _rate_limited(client_row):
        rl = client_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            return False, 0, rl, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for inv in invocations if isinstance(invocations, list) else []:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != client_row.get("id"):
                continue
            dt = _parse_dt_any(inv.get("created_at"))
            if dt is not None and dt >= cutoff:
                used += 1
        return used >= rl, used, rl, max(0, rl - used)

    def _record(tool_name, client_row, req_obj, status_val, http_status_code=None,
                response_json=None, error_code=None, error_message=None):
        now = _now_iso()
        inv = {
            "id": _gen_inv_id(),
            "client_id": (client_row.get("id") if isinstance(client_row, dict) else None),
            "tool_name": tool_name,
            "status": "received",
            "request_json": req_obj if isinstance(req_obj, dict) else {},
            "response_json": None,
            "http_status_code": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "ip_address": None,
            "user_agent": None,
            "trace_id": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        inv["status"] = "processing"
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        inv["status"] = status_val
        inv["http_status_code"] = http_status_code
        inv["response_json"] = response_json
        inv["error_code"] = error_code
        inv["error_message"] = error_message
        inv["duration_ms"] = int(max(0, min(300000, round((time.time() - t0) * 1000))))
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        return inv["id"]

    authed = _auth_client(api_key)
    if authed is None:
        inv_id = _record("version", None, {"api_key": api_key, "id": id}, "failed", http_status_code=401,
                         error_code="invalid_api_key", error_message="Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key", http_status_code=401, invocation_id=inv_id)
    if authed.get("status") != "active":
        inv_id = _record("version", authed, {"api_key": api_key, "id": id}, "failed", http_status_code=403,
                         error_code="client_disabled", error_message="Client is not active; access denied")
        return _err("UNAUTHORIZED", "Client is not active; access denied", http_status_code=403, invocation_id=inv_id)

    limited, used, rl, remaining = _rate_limited(authed)
    if limited:
        inv_id = _record("version", authed, {"api_key": api_key, "id": id}, "failed", http_status_code=429,
                         error_code="rate_limited",
                         error_message=f"Rate limit exceeded: allowed {rl}/min; retry after 1s")
        return _err("RATE_LIMIT", "Rate limit exceeded", http_status_code=429, invocation_id=inv_id, limit=rl, used=used, remaining=remaining)

    target = None
    for c in clients if isinstance(clients, list) else []:
        if isinstance(c, dict) and c.get("id") == id:
            target = c
            break

    if target is None:
        inv_id = _record("version", authed, {"id": id}, "failed", http_status_code=404,
                         error_code="not_found", error_message="API client not found")
        return _err("NOT_FOUND", "API client not found", http_status_code=404, invocation_id=inv_id)

    # Update last_seen_at for authed client
    now_iso = _now_iso()
    for c in clients if isinstance(clients, list) else []:
        if isinstance(c, dict) and c.get("id") == authed.get("id"):
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso
            _save("api_clients.json", clients)
            break

    resp = {"data": target}
    inv_id = _record("version", authed, {"id": id}, "succeeded", http_status_code=200, response_json=resp)
    resp["invocation_id"] = inv_id
    return resp

def api_clients_create(api_key, name, rate_limit_per_minute, notes=None, status=None, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0164000" if __import__("os").path.isdir("./environment_mix/0164000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _write(filename, loaded_obj, rows):
        if isinstance(loaded_obj, dict) and isinstance(loaded_obj.get("rows"), list):
            loaded_obj["rows"] = rows
            _save(filename, loaded_obj)
        else:
            _save(filename, rows)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    def _hash_presented_key(k):
        # IMPORTANT: authenticate by matching client-visible value OR id; never compare against stored hash.
        # For newly created clients we can store a deterministic hash for uniqueness/auditing.
        return "sha256$" + hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _complete_invocation(inv_id, inv_loaded, inv_rows, *, status, http_status_code, response_json=None, error_code=None, error_message=None, client_id=None):
        dur = int(max(0, round((time.time() - t0) * 1000)))
        for r in inv_rows:
            if r.get("id") == inv_id:
                # append-only enforcement: do not change tool_name/request_json/created_at
                r["status"] = status
                r["http_status_code"] = http_status_code
                r["response_json"] = response_json
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["duration_ms"] = dur
                r["updated_at"] = now_iso
                if client_id is not None:
                    r["client_id"] = client_id
                break
        _write("tool_invocations.json", inv_loaded, inv_rows)

    # -----------------------
    # Validate inputs first
    # -----------------------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", http_status_code=400)
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", http_status_code=400)
    if not isinstance(rate_limit_per_minute, int):
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer", http_status_code=400)
    if rate_limit_per_minute < 1 or rate_limit_per_minute > 100000:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 100000", http_status_code=400)
    if notes is not None and not isinstance(notes, str):
        return _err("VALIDATION_ERROR", "notes must be a string when provided", http_status_code=400)
    if status is None:
        status = "active"
    if status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked", http_status_code=400)

    # -----------------------
    # Create invocation row (management ops should still be logged)
    # tool_name is constrained to echo/ping/version in schema; to avoid violating constraints,
    # we attribute this management call to tool_name='echo' and store the actual endpoint in request_json.
    # -----------------------
    inv_loaded = _load("tool_invocations.json")
    inv_rows = _rows(inv_loaded)
    inv_id = "eco_inv_" + uuid.uuid4().hex[:26]
    inv_row = {
        "id": inv_id,
        "client_id": None,
        "tool_name": "echo",
        "status": "received",
        "request_json": {
            "endpoint": "api_clients_create",
            "api_key": api_key,
            "name": name,
            "rate_limit_per_minute": rate_limit_per_minute,
            "notes": notes,
            "status": status,
        },
        "response_json": None,
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "ip_address": None,
        "user_agent": None,
        "trace_id": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    inv_rows.append(inv_row)
    _write("tool_invocations.json", inv_loaded, inv_rows)

    # Transition received -> processing
    _complete_invocation(inv_id, inv_loaded, inv_rows, status="processing", http_status_code=102)

    # -----------------------
    # Authenticate management credential
    # Match api_key against a client-visible value or its id.
    # In this datastore we only have api_key_prefix (client-visible), id (client-visible), and api_key_hash (non-reversible).
    # Accept:
    #   - exact match of api_clients.id
    #   - exact match of api_clients.api_key_prefix
    #   - prefix match: presented startswith api_key_prefix (common pattern)
    # -----------------------
    clients_loaded = _load("api_clients.json")
    clients = _rows(clients_loaded)

    presented = api_key.strip()
    authed_client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        cid = c.get("id")
        pref = c.get("api_key_prefix")
        if (isinstance(cid, str) and presented == cid) or (isinstance(pref, str) and presented == pref):
            authed_client = c
            break
    if authed_client is None:
        for c in clients:
            if not isinstance(c, dict):
                continue
            pref = c.get("api_key_prefix")
            if isinstance(pref, str) and pref and presented.startswith(pref):
                authed_client = c
                break

    if authed_client is None:
        _complete_invocation(
            inv_id, inv_loaded, inv_rows,
            status="failed",
            http_status_code=401,
            error_code="invalid_api_key",
            error_message="Invalid API key credential for management operation",
        )
        return _err("UNAUTHORIZED", "Invalid API key credential for management operation", http_status_code=401, invocation_id=inv_id)

    # client must be active
    authed_client_id = authed_client.get("id")
    if authed_client.get("status") != "active":
        code = 403 if authed_client.get("status") in ("suspended", "revoked") else 401
        _complete_invocation(
            inv_id, inv_loaded, inv_rows,
            status="failed",
            http_status_code=code,
            error_code="client_disabled",
            error_message="Client is not active; access denied",
            client_id=authed_client_id,
        )
        return _err("UNAUTHORIZED", "Client is not active; access denied", http_status_code=code, invocation_id=inv_id)

    # -----------------------
    # Enforce rate limit for the authenticated client (rolling 60s window)
    # -----------------------
    limit = authed_client.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60

    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in inv_rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != authed_client_id:
            continue
        created = _parse_dt(r.get("created_at"))
        if created is None:
            continue
        if created >= window_start and created <= now:
            recent += 1

    # Count this request too (we haven't set client_id on invocation yet, but it's attributable)
    if recent + 1 > limit:
        retry_after = 1
        _complete_invocation(
            inv_id, inv_loaded, inv_rows,
            status="failed",
            http_status_code=429,
            error_code="rate_limited",
            error_message=f"Rate limit exceeded: allowed {limit}/min; retry after {retry_after}s",
            client_id=authed_client_id,
        )
        return _err("RATE_LIMIT", f"Rate limit exceeded: allowed {limit}/min; retry after {retry_after}s", http_status_code=429, retry_after_seconds=retry_after, invocation_id=inv_id)

    # Update last_seen_at for authed client
    for c in clients:
        if isinstance(c, dict) and c.get("id") == authed_client_id:
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso
            break
    _write("api_clients.json", clients_loaded, clients)

    # Attribute invocation to authed client now that auth passed
    _complete_invocation(inv_id, inv_loaded, inv_rows, status="processing", http_status_code=102, client_id=authed_client_id)

    # -----------------------
    # Create new client enforcing constraints
    # -----------------------
    # unique(name), unique(api_key_hash), unique(api_key_prefix)
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("name") == name:
            _complete_invocation(
                inv_id, inv_loaded, inv_rows,
                status="failed",
                http_status_code=409,
                error_code="conflict",
                error_message="Client name must be unique",
                client_id=authed_client_id,
            )
            return _err("CONFLICT", "Client name must be unique", http_status_code=409, field="name", invocation_id=inv_id)

    # For created client, treat the supplied api_key as the new client's raw key and store its hash.
    new_api_key_hash = _hash_presented_key(presented)

    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == new_api_key_hash:
            _complete_invocation(
                inv_id, inv_loaded, inv_rows,
                status="failed",
                http_status_code=409,
                error_code="conflict",
                error_message="api_key must be unique (hash collision)",
                client_id=authed_client_id,
            )
            return _err("CONFLICT", "api_key must be unique", http_status_code=409, field="api_key", invocation_id=inv_id)

    # Generate unique prefix (first 8 hex of hash), extend if collision
    base_prefix = hashlib.sha256(presented.encode("utf-8")).hexdigest()[:8]
    prefix = base_prefix
    suffix_len = 8
    while any(isinstance(c, dict) and c.get("api_key_prefix") == prefix for c in clients):
        suffix_len += 2
        prefix = hashlib.sha256(presented.encode("utf-8")).hexdigest()[:suffix_len]
        if suffix_len > 32:
            prefix = uuid.uuid4().hex[:12]
            if not any(isinstance(c, dict) and c.get("api_key_prefix") == prefix for c in clients):
                break

    new_id = _gen_id("eco_cli")
    new_row = {
        "id": new_id,
        "name": name,
        "status": status,
        "api_key_hash": new_api_key_hash,
        "api_key_prefix": prefix,
        "rate_limit_per_minute": rate_limit_per_minute,
        "notes": notes,
        "last_seen_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    clients.append(new_row)
    _write("api_clients.json", clients_loaded, clients)

    # Complete invocation
    _complete_invocation(
        inv_id, inv_loaded, inv_rows,
        status="succeeded",
        http_status_code=201,
        response_json=new_row,
        client_id=authed_client_id,
    )

    return {
        "client": new_row,
        "invocation_id": inv_id
    }

def api_clients_update(api_key, id, name=None, rate_limit_per_minute=None, notes=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0164000" if __import__("os").path.isdir("./environment_mix/0164000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if _extra:
        return _err("VALIDATION_ERROR", f"Unknown field(s): {', '.join(sorted(_extra.keys()))}")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if notes is not None and not isinstance(notes, str):
        return _err("VALIDATION_ERROR", "notes must be a string")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")
    if rate_limit_per_minute is not None:
        if not isinstance(rate_limit_per_minute, int):
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer")
        if rate_limit_per_minute < 1 or rate_limit_per_minute > 60000:
            return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 60000")

    clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_inv_id():
        return "eco_inv_" + uuid.uuid4().hex[:26]

    def _parse_dt_any(s):
        if not isinstance(s, str) or not s:
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _auth_client(key):
        k = key.strip()
        for c in clients if isinstance(clients, list) else []:
            if not isinstance(c, dict):
                continue
            pfx = c.get("api_key_prefix")
            if k == c.get("id") or k == pfx:
                return c
            if isinstance(pfx, str) and pfx and k.startswith(pfx):
                return c
            if k == c.get("api_key_hash"):
                return c
        return None

    def _rate_limited(client_row):
        rl = client_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            return False, 0, rl, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for inv in invocations if isinstance(invocations, list) else []:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != client_row.get("id"):
                continue
            dt = _parse_dt_any(inv.get("created_at"))
            if dt is not None and dt >= cutoff:
                used += 1
        return used >= rl, used, rl, max(0, rl - used)

    def _record(tool_name, client_row, req_obj, status_val, http_status_code=None,
                response_json=None, error_code=None, error_message=None):
        now = _now_iso()
        inv = {
            "id": _gen_inv_id(),
            "client_id": (client_row.get("id") if isinstance(client_row, dict) else None),
            "tool_name": tool_name,
            "status": "received",
            "request_json": req_obj if isinstance(req_obj, dict) else {},
            "response_json": None,
            "http_status_code": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "ip_address": None,
            "user_agent": None,
            "trace_id": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        inv["status"] = "processing"
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        inv["status"] = status_val
        inv["http_status_code"] = http_status_code
        inv["response_json"] = response_json
        inv["error_code"] = error_code
        inv["error_message"] = error_message
        inv["duration_ms"] = int(max(0, min(300000, round((time.time() - t0) * 1000))))
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        return inv["id"]

    authed = _auth_client(api_key)
    if authed is None:
        inv_id = _record("version", None, {"id": id}, "failed", http_status_code=401,
                         error_code="invalid_api_key", error_message="Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key", http_status_code=401, invocation_id=inv_id)
    if authed.get("status") != "active":
        inv_id = _record("version", authed, {"id": id}, "failed", http_status_code=403,
                         error_code="client_disabled", error_message="Client is not active; access denied")
        return _err("UNAUTHORIZED", "Client is not active; access denied", http_status_code=403, invocation_id=inv_id)

    limited, used, rl, remaining = _rate_limited(authed)
    if limited:
        inv_id = _record("version", authed, {"id": id}, "failed", http_status_code=429,
                         error_code="rate_limited", error_message=f"Rate limit exceeded: allowed {rl}/min; retry after 1s")
        return _err("RATE_LIMIT", "Rate limit exceeded", http_status_code=429, invocation_id=inv_id, limit=rl, used=used, remaining=remaining)

    if not isinstance(clients, list):
        clients = []

    idx = None
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == id:
            idx = i
            break
    if idx is None:
        inv_id = _record("version", authed, {"id": id}, "failed", http_status_code=404,
                         error_code="not_found", error_message="API client not found")
        return _err("NOT_FOUND", "API client not found", http_status_code=404, invocation_id=inv_id)

    row = clients[idx]

    # Uniqueness: name (if changing)
    if name is not None and name != row.get("name"):
        for c in clients:
            if isinstance(c, dict) and c.get("id") != id and c.get("name") == name:
                inv_id = _record("version", authed, {"id": id, "name": name}, "failed", http_status_code=409,
                                 error_code="conflict", error_message="unique(name) violated")
                return _err("CONFLICT", "A client with this name already exists", http_status_code=409, invocation_id=inv_id)

    # Lifecycle transition enforcement
    if status is not None and status != row.get("status"):
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        cur = row.get("status")
        if cur not in transitions or status not in transitions[cur]:
            inv_id = _record("version", authed, {"id": id, "status": status}, "failed", http_status_code=409,
                             error_code="invalid_transition", error_message=f"Invalid transition {cur} -> {status}")
            return _err("INVALID_TRANSITION", f"Invalid status transition: {cur} -> {status}", http_status_code=409, invocation_id=inv_id)

    # Apply updates (immutable: id, api_key_hash, api_key_prefix, created_at)
    changed = False
    if name is not None and name != row.get("name"):
        row["name"] = name
        changed = True
    if notes is not None and notes != row.get("notes"):
        row["notes"] = notes
        changed = True
    if rate_limit_per_minute is not None and rate_limit_per_minute != row.get("rate_limit_per_minute"):
        row["rate_limit_per_minute"] = rate_limit_per_minute
        changed = True
    if status is not None and status != row.get("status"):
        row["status"] = status
        changed = True

    if not changed:
        # idempotent update: still a successful mutation with no changes? Real APIs often return current resource.
        # Ensure "no success without effect" applies to mutations that matched no row; here we did match the row.
        pass

    row["updated_at"] = _now_iso()
    clients[idx] = row
    _save("api_clients.json", clients)

    # Update last_seen_at for authed client
    now_iso = _now_iso()
    for c in clients:
        if isinstance(c, dict) and c.get("id") == authed.get("id"):
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso
            _save("api_clients.json", clients)
            break

    resp = {"data": row}
    inv_id = _record("version", authed, {"id": id, "name": name, "rate_limit_per_minute": rate_limit_per_minute, "notes": notes, "status": status}, "succeeded",
                     http_status_code=200, response_json=resp)
    resp["invocation_id"] = inv_id
    return resp

def tool_invocations_list(api_key, client_id=None, tool_name=None, status=None, trace_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0164000" if __import__("os").path.isdir("./environment_mix/0164000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if _extra:
        return _err("VALIDATION_ERROR", f"Unknown field(s): {', '.join(sorted(_extra.keys()))}")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if client_id is not None and not isinstance(client_id, str):
        return _err("VALIDATION_ERROR", "client_id must be a string")
    if tool_name is not None and tool_name not in ("echo", "ping", "version"):
        return _err("VALIDATION_ERROR", "tool_name must be one of: echo, ping, version")
    if status is not None and status not in ("received", "processing", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "status must be one of: received, processing, succeeded, failed")
    if trace_id is not None and not isinstance(trace_id, str):
        return _err("VALIDATION_ERROR", "trace_id must be a string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    clients = _load("api_clients.json")
    invocations = _load("tool_invocations.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_inv_id():
        return "eco_inv_" + uuid.uuid4().hex[:26]

    def _parse_dt_filter(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    def _parse_dt_any(s):
        if not isinstance(s, str) or not s:
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    after_dt, err = _parse_dt_filter(created_after, "created_after")
    if err:
        return err
    before_dt, err = _parse_dt_filter(created_before, "created_before")
    if err:
        return err
    if after_dt and before_dt and after_dt > before_dt:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    def _auth_client(key):
        k = key.strip()
        for c in clients if isinstance(clients, list) else []:
            if not isinstance(c, dict):
                continue
            pfx = c.get("api_key_prefix")
            if k == c.get("id") or k == pfx:
                return c
            if isinstance(pfx, str) and pfx and k.startswith(pfx):
                return c
            if k == c.get("api_key_hash"):
                return c
        return None

    def _rate_limited(client_row):
        rl = client_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1:
            return False, 0, rl, None
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        used = 0
        for inv in invocations if isinstance(invocations, list) else []:
            if not isinstance(inv, dict):
                continue
            if inv.get("client_id") != client_row.get("id"):
                continue
            dt = _parse_dt_any(inv.get("created_at"))
            if dt is not None and dt >= cutoff:
                used += 1
        return used >= rl, used, rl, max(0, rl - used)

    def _record(tool_name_for_log, client_row, req_obj, status_val, http_status_code=None,
                response_json=None, error_code=None, error_message=None):
        now = _now_iso()
        inv = {
            "id": _gen_inv_id(),
            "client_id": (client_row.get("id") if isinstance(client_row, dict) else None),
            "tool_name": tool_name_for_log,
            "status": "received",
            "request_json": req_obj if isinstance(req_obj, dict) else {},
            "response_json": None,
            "http_status_code": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "ip_address": None,
            "user_agent": None,
            "trace_id": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        inv["status"] = "processing"
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        inv["status"] = status_val
        inv["http_status_code"] = http_status_code
        inv["response_json"] = response_json
        inv["error_code"] = error_code
        inv["error_message"] = error_message
        inv["duration_ms"] = int(max(0, min(300000, round((time.time() - t0) * 1000))))
        inv["updated_at"] = _now_iso()
        _save("tool_invocations.json", invocations)
        return inv["id"]

    authed = _auth_client(api_key)
    if authed is None:
        inv_id = _record("version", None, {"api_key": api_key}, "failed", http_status_code=401,
                         error_code="invalid_api_key", error_message="Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key", http_status_code=401, invocation_id=inv_id)
    if authed.get("status") != "active":
        inv_id = _record("version", authed, {"api_key": api_key}, "failed", http_status_code=403,
                         error_code="client_disabled", error_message="Client is not active; access denied")
        return _err("UNAUTHORIZED", "Client is not active; access denied", http_status_code=403, invocation_id=inv_id)

    limited, used, rl, remaining = _rate_limited(authed)
    if limited:
        inv_id = _record("version", authed, {}, "failed", http_status_code=429,
                         error_code="rate_limited", error_message=f"Rate limit exceeded: allowed {rl}/min; retry after 1s")
        return _err("RATE_LIMIT", "Rate limit exceeded", http_status_code=429, invocation_id=inv_id, limit=rl, used=used, remaining=remaining)

    # Filter
    rows = [r for r in (invocations if isinstance(invocations, list) else []) if isinstance(r, dict)]
    if client_id is not None:
        rows = [r for r in rows if r.get("client_id") == client_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if trace_id is not None:
        rows = [r for r in rows if r.get("trace_id") == trace_id]
    if after_dt is not None:
        rows = [r for r in rows if (_parse_dt_any(r.get("created_at")) is not None and _parse_dt_any(r.get("created_at")) >= after_dt)]
    if before_dt is not None:
        rows = [r for r in rows if (_parse_dt_any(r.get("created_at")) is not None and _parse_dt_any(r.get("created_at")) <= before_dt)]

    # Sort by created_at desc then id desc
    def _sort_key(r):
        dt = _parse_dt_any(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    rows.sort(key=_sort_key, reverse=True)

    # Cursor: treat as invocation id; return entries after it in the current sort order
    if cursor:
        seen = False
        filtered = []
        for r in rows:
            if not seen:
                if r.get("id") == cursor:
                    seen = True
                continue
            filtered.append(r)
        rows = filtered

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = page[-1]["id"] if (has_more and page and isinstance(page[-1].get("id"), str)) else None

    # Update last_seen_at for authed client
    now_iso = _now_iso()
    for c in clients if isinstance(clients, list) else []:
        if isinstance(c, dict) and c.get("id") == authed.get("id"):
            c["last_seen_at"] = now_iso
            c["updated_at"] = now_iso
            _save("api_clients.json", clients)
            break

    resp = {"data": page, "meta": {"total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "limit": limit}}
    inv_id = _record("version", authed, {
        "client_id": client_id, "tool_name": tool_name, "status": status, "trace_id": trace_id,
        "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor
    }, "succeeded", http_status_code=200, response_json=resp)
    resp["invocation_id"] = inv_id
    return resp
